package com.dat.cms.controller;
import com.dat.cms.service.*;import java.math.BigDecimal;import java.util.*;
import org.springframework.security.access.AccessDeniedException;import org.springframework.security.core.Authentication;import org.springframework.stereotype.Controller;import org.springframework.ui.Model;import org.springframework.web.bind.annotation.*;import org.springframework.web.servlet.mvc.support.RedirectAttributes;
@Controller public class WebController {
 private final ApprovalService approvals;private final ContractService contracts;public WebController(ApprovalService a,ContractService c){approvals=a;contracts=c;}
 @GetMapping("/login") public String login(){return "login";}
 @GetMapping("/") public String home(Authentication auth,Model m){m.addAttribute("username",auth.getName());m.addAttribute("contracts",approvals.all());m.addAttribute("success",m.getAttribute("success"));m.addAttribute("error",m.getAttribute("error"));return "home";}
 @GetMapping("/contracts/new") public String form(Model m){m.addAttribute("form",new ContractForm());options(m);return "contract-form";}
 @PostMapping("/contracts") public String create(@ModelAttribute ContractForm f,Authentication a,Model m,RedirectAttributes r){if(f.contractNo==null||f.contractNo.isBlank()||f.description==null||f.description.isBlank()||f.contractValue==null||f.contractValue.signum()<0){m.addAttribute("error","Please complete all required fields. Value must be zero or greater.");options(m);m.addAttribute("form",f);return "contract-form";}try{long id=contracts.create(f.contractNo.trim(),f.description.trim(),f.departmentId,f.partyId,f.categoryId,f.contractTypeId,f.currencyId,f.contractValue,a.getName());r.addFlashAttribute("success","Draft contract created (ID "+id+"). Submit it from the dashboard.");}catch(RuntimeException e){r.addFlashAttribute("error",e.getMessage());}return "redirect:/";}
 @PostMapping("/contracts/{id}/submit") public String submit(@PathVariable long id,Authentication a,RedirectAttributes r){try{approvals.submit(id,a.getName());r.addFlashAttribute("success","Submitted to Department Head.");}catch(RuntimeException e){r.addFlashAttribute("error",e.getMessage());}return "redirect:/";}
 @GetMapping("/approvals") public String list(Authentication a,Model m){String role=approvalRole(a);m.addAttribute("roleCode",role);m.addAttribute("pending",approvals.pending(role));return "approvals";}
 @PostMapping("/approvals/{id}/approve") public String approve(@PathVariable long id,@RequestParam(required=false)String comments,Authentication a,RedirectAttributes r){try{approvals.approve(id,a.getName(),comments);r.addFlashAttribute("success","Approved. Contract moved to the next stage.");}catch(RuntimeException e){r.addFlashAttribute("error",e.getMessage());}return "redirect:/approvals";}
 @PostMapping("/approvals/{id}/reject") public String reject(@PathVariable long id,@RequestParam String reason,Authentication a,RedirectAttributes r){try{approvals.reject(id,a.getName(),reason);r.addFlashAttribute("success","Rejected. Record retained; removed from pending approvals.");}catch(RuntimeException e){r.addFlashAttribute("error",e.getMessage());}return "redirect:/approvals";}
 @GetMapping("/rejected") public String rejected(Model m){m.addAttribute("contracts",approvals.all().stream().filter(c->"Rejected".equalsIgnoreCase(String.valueOf(c.get("status_name")))).toList());return "rejected";}
 private String approvalRole(Authentication a){for(String role:List.of("DEPARTMENT_HEAD","PMO","CONTRACT_MANAGER"))if(a.getAuthorities().stream().anyMatch(x->x.getAuthority().equals("ROLE_"+role)))return role;if(a.getAuthorities().stream().anyMatch(x->x.getAuthority().equals("ROLE_ADMIN")))return "DEPARTMENT_HEAD";throw new AccessDeniedException("No approval role assigned.");}
 private void options(Model m){m.addAttribute("departments",contracts.departments());m.addAttribute("parties",contracts.parties());m.addAttribute("categories",contracts.categories());m.addAttribute("types",contracts.types());m.addAttribute("currencies",contracts.currencies());}
 public static class ContractForm {public String contractNo,description;public int departmentId,partyId,categoryId,contractTypeId,currencyId;public BigDecimal contractValue=BigDecimal.ZERO;public String getContractNo(){return contractNo;}public void setContractNo(String v){contractNo=v;}public String getDescription(){return description;}public void setDescription(String v){description=v;}public int getDepartmentId(){return departmentId;}public void setDepartmentId(int v){departmentId=v;}public int getPartyId(){return partyId;}public void setPartyId(int v){partyId=v;}public int getCategoryId(){return categoryId;}public void setCategoryId(int v){categoryId=v;}public int getContractTypeId(){return contractTypeId;}public void setContractTypeId(int v){contractTypeId=v;}public int getCurrencyId(){return currencyId;}public void setCurrencyId(int v){currencyId=v;}public BigDecimal getContractValue(){return contractValue;}public void setContractValue(BigDecimal v){contractValue=v;}}
}